INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
  (34851, 0, 10, 'Die!', 12, 0, 50, 0, 0, 0, 0, 0, 'combat Say'),
  (44086, 1, 0, 'The... They promised that we would have security...', 12, 0, 33, 0, 0, 0, 0, 0, 'Panicked Citizen Random Saying'),
  (44086, 1, 1, 'It means we go from here! The screams are stronger every night.', 12, 0, 33, 0, 0, 0, 0, 0, 'Panicked Citizen Random Saying'),
  (44086, 1, 2, 'Why are the doors closed data?', 12, 0, 33, 0, 0, 0, 0, 0, 'Panicked Citizen Random Saying'),
  (35378, 0, 0, 'This mastiff will help you find the hidden worgen.', 12, 0, 100, 0, 0, 0, 0, 0, 'Lorna - Quest Accept'),
  (35550, 0, 0, 'Fire!', 14, 0, 100, 0, 0, 0, 0, 0, 'General King Greymane at Barricades'),
  (35550, 0, 1, 'Hold the barricades! Do not give them an inch!', 14, 0, 100, 0, 0, 0, 0, 0, 'General King Greymane at Barricades'),
  (35550, 0, 2, 'Keep them back!', 14, 0, 100, 0, 0, 0, 0, 0, 'General King Greymane at Barricades'),
  (35906, 0, 0, 'We''ve got Aranas! Fire at will!', 14, 0, 100, 5, 0, 0, 0, 0, ''),
  (35112, 0, 0, 'Enough! I''ve made up my mind. We need Crowley on our side.', 12, 0, 100, 1, 2000, 0, 0, 0, ''),
  (35115, 0, 0, 'We ought to leave Crowley in prison with those beasts!', 12, 0, 100, 5, 2000, 0, 0, 0, ''),
  (35905, 0, 0, 'Rescue Krennan Aranas by using your vehicle''s ability.', 41, 0, 100, 0, 0, 0, 0, 0, ''),
  (35753, 0, 0, 'Help! Up here!', 14, 0, 100, 0, 0, 0, 0, 0, ''),
  (50474, 0, 0, 'They''re turning our people into MONSTERS!!', 14, 0, 100, 0, 0, 0, 0, 0, 'Gilneas City Guard'),
  (50474, 0, 1, 'Don''t look into their eyes!  They''re not the people you once knew!', 14, 0, 100, 0, 0, 0, 0, 0, 'Gilneas City Guard'),
  (50474, 0, 2, 'Hold them back!  We must protect the survivors!', 14, 0, 100, 0, 0, 0, 0, 0, 'Gilneas City Guard'),
  (35911, 1, 0, 'I''ll stay behind with the Royal Guard, father. It is my duty to Gilneas.', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (35911, 2, 0, 'We were fools to take up arms against each other, Darius. The worgen would''ve never stood a chance.', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (35911, 0, 0, 'If we can make it past the gates into Duskhaven we''ll be safe. The eastern mountains are virtually impassable.', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (35552, 2, 0, 'My men and I will hole up inside the Light''s Dawn Cathedral. I''ve already given the order and the cannons are on their way. Lead our people well, Genn.', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (35552, 0, 0, 'We need to keep the worgen''s attention in the city, Genn. It''s the only shot we have for the survivors to make it to Duskhaven.', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (35552, 1, 0, 'Not a chance, boy. Gilneas is going to need its king''s undivided attention. Can''t have your father wondering whether his child is alive or not.', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (35551, 0, 0, 'I''ll stay behind with the Royal Guard, father.  It is my duty to Gilneas.', 12, 0, 100, 0, 0, 0, 0, 0, 'Prince Liam Greymane'),
  (35230, 1, 0, 'Come and get us, you motherless beasts!', 14, 0, 100, 5, 0, 0, 0, 0, ''),
  (35230, 0, 0, 'Let''s round up as many of them as we can. Every worgen chasing us is one less worgen chasing the survivors!', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (35370, 0, 0, 'You''ve been bitten by a worgen. It''s probably nothing, but it sure stings a little.$B$B|TInterfaceIconsINV_Misc_monsterfang_02.blp:12|t', 41, 0, 100, 0, 0, 0, 0, 0, ''),
  (35118, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 2000, 0, 0, 0, ''),
  (75130, 0, 0, 'Survive while holding back the worgen!', 41, 0, 100, 0, 0, 0, 0, 0, 'say Text'),
  (35369, 0, 0, 'My hands... don''t look at my hands!!', 14, 0, 100, 0, 2000, 0, 0, 0, ''),
  (35369, 0, 1, 'Make it stop!', 14, 0, 100, 0, 2000, 0, 0, 0, ''),
  (35369, 0, 2, 'The pain is unbearable!', 14, 0, 100, 0, 2000, 0, 0, 0, ''),
  (35369, 0, 3, 'I can''t fight it!', 14, 0, 100, 0, 2000, 0, 0, 0, ''),
  (35369, 0, 4, 'What''s wrong with me?', 14, 0, 100, 0, 2000, 0, 0, 0, ''),
  (35369, 0, 5, 'My face... What''s wrong with my face!', 14, 0, 100, 0, 2000, 0, 0, 0, ''),
  (35369, 1, 0, 'You''ve been bitten by a worgen. It''s probably nothing, but it sure stings a little.', 41, 0, 100, 0, 0, 0, 0, 0, ''),
  (36330, 0, 0, 'Give it up, Krennan. It''s time to put this one down. It''s protocol.', 12, 0, 100, 274, 0, 0, 0, 0, 'Godfrey'),
  (36440, 0, 0, 'I... I thought I was a goner. Thanks.', 12, 0, 100, 1, 0, 0, 0, 0, 'Drowning Watchman'),
  (37067, 0, 3, 'You got here just in time. Thanks!', 12, 0, 100, 1, 0, 0, 0, 0, ''),
  (37875, 0, 0, 'No ... I''d rather die than have one of yours for a king!', 12, 0, 100, 0, 0, 0, 0, 0, ''),
  (34851, 0, 13, 'Help!', 12, 0, 50, 22, 0, 0, 0, 0, 'combat Say'),
  (34851, 1, 0, 'What... what are those things on the rooftops?', 12, 0, 75, 0, 0, 0, 0, 0, ''),
